style.css:
body {
  background: url("https://i.pinimg.com/736x/f2/c4/71/f2c4710a45e47ab54e8f3878e44cbc1c.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
}

body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.6); /* затемнение */
  z-index: -1;
}
